-- Let a map editor undo and redo painting a tile.
-- level-editor-undo: original MIT-licensed native educational port.
-- Generated by tools/ports/generate.py; edit the specification to preserve parity.
-- Input: [width,height,...[operation,cell,value]]
-- Output: [...final_grid]
-- Operations: 0 paint, 1 undo, 2 redo. Cell ID is y*width+x. New paint discards the redo branch.
-- Ignored unused cell/value fields must still be supplied.
-- Precondition: finite, correctly shaped data; integer indices/counts/IDs.
-- See ../PORTS.md for examples, limits, and the shared test fixtures.

-- Count how many numbers are in this list.
local function port_length(a) return #a end
-- Read one number at a zero-based position; stop if that position does not exist.
local function port_get(a,i) assert(i>=0 and i==math.floor(i) and i<#a,"index"); return a[i+1] end
-- Replace a number at an existing position in the list.
local function port_put(a,i,v) port_get(a,i); a[i+1]=v end
-- Add one number to the end of the list.
local function port_push(a,v) a[#a+1]=v end
-- Make a separate list so editing it cannot change the old list.
local function port_copy(a) local b={} for i,v in ipairs(a) do b[i]=v end return b end

-- 1. Before painting, remember the old tile and the new tile.
-- 2. Undo restores the old tile and moves backward in the edit history.
-- 3. Redo puts the new tile back and moves forward.
-- 4. Painting after undo throws away the abandoned future edits.
local function compute(data)
    local w = 0
    local h = 0
    local grid = {}
    local history = {}
    local cursor = 0
    local i = 0
    local operation = 0
    local cell = 0
    local value = 0
    local kept = {}
    local j = 0
    w = port_get(data, 0)
    h = port_get(data, 1)
    if ((w < 1) or (h < 1)) then
        return {-(1)}
    end
    grid = {}
    history = {}
    cursor = 0
    i = 0
    while (i < (w * h)) do
        port_push(grid, 0)
        i = i + 1
    end
    i = 2
    while (i < port_length(data)) do
        operation = port_get(data, i)
        cell = port_get(data, (i + 1))
        value = port_get(data, (i + 2))
        if (operation == 0) then
            if ((cell < 0) or (cell >= (w * h))) then
                return {-(1)}
            end
            kept = {}
            j = 0
            while (j < (cursor * 3)) do
                port_push(kept, port_get(history, j))
                j = j + 1
            end
            history = port_copy(kept)
            port_push(history, cell)
            port_push(history, port_get(grid, cell))
            port_push(history, value)
            cursor = cursor + 1
            port_put(grid, cell, value)
        else
            if ((operation == 1) and (cursor > 0)) then
                cursor = cursor - 1
                port_put(grid, port_get(history, (cursor * 3)), port_get(history, ((cursor * 3) + 1)))
            else
                if ((operation == 2) and ((cursor * 3) < port_length(history))) then
                    port_put(grid, port_get(history, (cursor * 3)), port_get(history, ((cursor * 3) + 2)))
                    cursor = cursor + 1
                end
            end
        end
        i = i + 3
    end
    return grid
end
return {compute=compute}
